import type { Verdict, RiskTier, InterceptorViolation } from '../contract/types.ts';

// ── Input type ────────────────────────────────────────────────────────────────

/**
 * ApprovalStatus widened for internal use: includes 'unresolved' (rule 8) which
 * is NOT part of the shared contract ApprovalStatus (approved|not_approved|banned).
 * The resolver emits 'unresolved' when no catalog entity matched the tool name.
 */
export type ComposeApprovalStatus = 'approved' | 'not_approved' | 'banned' | 'unresolved';

export interface ComposeVerdictInput {
  /** Approval status from the entity-approval resolver. */
  approval_status: ComposeApprovalStatus;
  /** SCOPE risk tier for this tool; null when unknown or not classified. */
  scope_tier: RiskTier | null;
  /** true for non-mcp__ tools (Bash/Edit/Write/Grep/etc.) — not gated in v1. */
  isNativeTool: boolean;
  /** true when the tool name matches the bundled catastrophic deny-list. */
  isCatastrophic: boolean;
  /** Violations from policy evaluation; rules 4/11 inspect status:'block'|'notify'. */
  violations: InterceptorViolation[];
  /** true when the policy engine was unreachable (fail-CLOSED → ASK). */
  engineUnreachable: boolean;
  /** Policy mode; 'enforce' enables rules 4/6-BLOCK on blocking violations. */
  mode: 'enforce' | 'permissive';
}

export interface ComposeVerdictOutput {
  verdict: Verdict;
  /** Absent for ALLOW. Present for BLOCK/ASK and when a rule names a reason. */
  reason?: string;
  /** The rule tag that fired, verbatim from the §4.4 table. */
  appliedRule: string;
}

// ── Rule table (12 rules, first match wins) ───────────────────────────────────

/**
 * composeVerdict — deterministic, pure, first-match-wins rule table.
 *
 * Rules match the EXACT identifiers from §4.4:
 *   engine_unreachable | catastrophic_deny_list | banned_entity |
 *   enforce_violation | native_auto_allow | scope_critical | scope_high |
 *   not_approved | scope_medium_not_approved | approved_low_risk |
 *   notify_only | default_ask
 */
export function composeVerdict(input: ComposeVerdictInput): ComposeVerdictOutput {
  const {
    approval_status,
    scope_tier,
    isNativeTool,
    isCatastrophic,
    violations,
    engineUnreachable,
    mode,
  } = input;

  // Rule 1 — eval-error / engine-unreachable (daemon-up)
  // Fail-CLOSED → ASK. Never silent ALLOW on uncertainty.
  if (engineUnreachable) {
    return { verdict: 'ASK', reason: 'Policy engine unreachable', appliedRule: 'engine_unreachable' };
  }

  // Rule 2 — isCatastrophicMatch (bundled native deny-list)
  // Checked BEFORE native_auto_allow so a catastrophic native tool is still blocked.
  if (isCatastrophic) {
    return { verdict: 'BLOCK', reason: 'Tool matches catastrophic deny-list', appliedRule: 'catastrophic_deny_list' };
  }

  // Rule 3 — approval_status == banned
  if (approval_status === 'banned') {
    return { verdict: 'BLOCK', reason: 'Entity is banned', appliedRule: 'banned_entity' };
  }

  // Rule 4 — blocking policy violation (status:'block') AND enforce-mode
  const hasBlockViolation = violations.some((v) => v.status === 'block');
  if (hasBlockViolation && mode === 'enforce') {
    const details = violations.filter((v) => v.status === 'block').map((v) => v.details).join('; ');
    return { verdict: 'BLOCK', reason: `Policy violation in enforce mode: ${details}`, appliedRule: 'enforce_violation' };
  }

  // Rule 5 — isNativeTool (v1, not catastrophic — already guarded by rule 2)
  // SCREEN+EVIDENCE auto-ALLOW for native tools.
  if (isNativeTool) {
    return { verdict: 'ALLOW', appliedRule: 'native_auto_allow' };
  }

  // Rule 6 — scope_tier == critical
  // banned/enforced have already fired (rules 3/4); remaining discriminant is mode.
  if (scope_tier === 'critical') {
    if (mode === 'enforce') {
      return { verdict: 'BLOCK', reason: 'Critical-risk tool in enforce mode', appliedRule: 'scope_critical' };
    }
    return { verdict: 'ASK', reason: 'Critical-risk tool requires human review', appliedRule: 'scope_critical' };
  }

  // Rule 7 — scope_tier == high
  if (scope_tier === 'high') {
    return { verdict: 'ASK', reason: 'High-risk tool requires human review', appliedRule: 'scope_high' };
  }

  // Rule 8 — approval_status in {not_approved, unresolved}
  if (approval_status === 'not_approved' || approval_status === 'unresolved') {
    return { verdict: 'ASK', reason: 'Tool is not approved', appliedRule: 'not_approved' };
  }

  // Rule 9 — scope_tier == medium AND approval_status != approved
  if (scope_tier === 'medium' && approval_status !== 'approved') {
    return { verdict: 'ASK', reason: 'Medium-risk tool requires approval', appliedRule: 'scope_medium_not_approved' };
  }

  // Rule 10 — approved AND scope_tier ∉ {high, critical} → ALLOW
  // Covers low, medium, and null tiers for approved tools.
  // high/critical are consumed by rules 6/7 before reaching here; at this point
  // scope_tier is narrowed to 'low' | 'medium' | null by prior rules.
  // Positive enumeration makes the scope boundary explicit and is defensive against
  // future rule reordering that could silently pass high/critical into this check.
  if (approval_status === 'approved' && (scope_tier === 'low' || scope_tier === 'medium' || scope_tier === null)) {
    return { verdict: 'ALLOW', appliedRule: 'approved_low_risk' };
  }

  // Rule 11 — notify-only (permissive) violations, approved
  // NOTE: this rule is now subsumed by rule 10 for all approved inputs (rules 6/7 consume
  // high/critical, rules 3/8 consume banned/not_approved/unresolved, so only approved reaches
  // here and rule 10 fires first). Retained as a forward-compat safety net for future inputs
  // (new approval statuses, or if rule 10 is narrowed back). Faithfully mirrors the §4.4 table.
  const hasOnlyNotifyViolations = violations.length > 0 && violations.every((v) => v.status === 'notify');
  if (hasOnlyNotifyViolations && approval_status === 'approved') {
    return { verdict: 'ALLOW', appliedRule: 'notify_only' };
  }

  // Rule 12 — DEFAULT
  // Never silent ALLOW. Fail-CLOSED to ASK on any unclassified case.
  // NOTE: currently unreachable for all approved inputs (subsumed by rule 10). Retained as a
  // fail-CLOSED safety net for future inputs that may not be consumed by rules 1–11.
  return { verdict: 'ASK', reason: 'No rule matched; defaulting to ASK', appliedRule: 'default_ask' };
}
